// The friend of InfillPatternRegistry that binds rows.
class InfillPatternLibraryLoader
{
public:
    static bool bind(const BuiltinInfillLoad &load) { return InfillPatternRegistry::bind_library(load.pattern, *load.library, load.file); }
    static void set_unbound(const BuiltinInfillLoad &load) { InfillPatternRegistry::set_unbound(load.pattern, load.file, load.error); }
};

