// ---- Checks ----

// Size of the 1.0 layout of a struct: up to the end of its last 1.0 field.
#define ORCA_INFILL_BUILTIN_V1_SIZE(TYPE, LAST) (offsetof(TYPE, LAST) + sizeof(TYPE::LAST))

// What the library of a row describes: the calls of run(), the traits and the object states.
struct RowContract
{
    uint32_t calls       = 0;
    uint32_t traits      = 0;
    uint32_t state_kinds = 0;
};

RowContract contract(const InfillPatternDescriptor &row)
{
    RowContract out;
    if (row.id == ipConcentricInternal) {
        out.calls = 1u << ORCA_INFILL_CALL_CONCENTRIC_INTERNAL;
    } else {
        out.calls = 1u << ORCA_INFILL_CALL_FILL_SURFACE;
        if (row.has(ipfArachne))
            out.calls |= 1u << ORCA_INFILL_CALL_FILL_ARACHNE;
        if (row.id == ipLockedZag)
            out.calls |= 1u << ORCA_INFILL_CALL_LOCKED_ZAG;
    }
    if (row.has(ipfNoSort))
        out.traits |= ORCA_INFILL_TRAIT_NO_SORT;
    if (row.has(ipfOctree))
        out.state_kinds |= 1u << ORCA_INFILL_STATE_OCTREE;
    if (row.has(ipfAdaptiveDensity))
        out.state_kinds |= 1u << ORCA_INFILL_STATE_ADAPTIVE_FIELD;
    if (row.id == ipLightning)
        out.state_kinds |= (1u << ORCA_INFILL_STATE_LIGHTNING) | (1u << ORCA_INFILL_STATE_LIGHTNING_SUPPORT);
    return out;
}

// The reason the library the entry returned for row is rejected; empty when it passes every check after the first.
std::string check_library(const InfillPatternDescriptor &row, const orca_infill_builtin_library *library, const std::string &entry_log)
{
    if (library == nullptr)
        return entry_log.empty() ? "belongs to another OrcaSlicer build" : "belongs to another OrcaSlicer build (" + entry_log + ")";
    if (library->struct_size < ORCA_INFILL_BUILTIN_V1_SIZE(orca_infill_builtin_library, query_state) ||
        library->abi_major != ORCA_INFILL_BUILTIN_ABI_MAJOR)
        return "belongs to another OrcaSlicer build (pattern library ABI " + std::to_string(library->abi_major) + "." +
               std::to_string(library->abi_minor) + ")";
    if (library->build_id == nullptr || std::strcmp(library->build_id, ORCA_INFILL_BUILD_ID) != 0)
        return std::string("belongs to another OrcaSlicer build (") + (library->build_id != nullptr ? library->build_id : "no build id") + ")";
    const orca_infill_builtin_row *served = library->row_count == 1 && library->rows != nullptr ? library->rows[0] : nullptr;
    if (served == nullptr || served->struct_size < ORCA_INFILL_BUILTIN_V1_SIZE(orca_infill_builtin_row, state_kinds))
        return "does not serve exactly one pattern";
    if (served->pattern != int32_t(row.id) || ! InfillPatternRegistry::same_key(served->key, row.key))
        return "serves another pattern (" + std::to_string(served->pattern) + " " + (served->key != nullptr ? served->key : "internal") + ")";
    const RowContract expected = contract(row);
    if (served->calls != expected.calls)
        return "serves other calls of its pattern";
    if (served->traits != expected.traits)
        return "describes its pattern differently";
    if (served->state_kinds != expected.state_kinds)
        return "prepares other object states for its pattern";
    if (library->set_scaling_factor == nullptr || library->create == nullptr || library->destroy == nullptr || library->run == nullptr ||
        (expected.state_kinds != 0 && (library->prepare_state == nullptr || library->release_state == nullptr)) ||
        ((expected.state_kinds & (1u << ORCA_INFILL_STATE_LIGHTNING_SUPPORT)) != 0 && library->query_state == nullptr))
        return "is incomplete";
    return {};
}

// Calls the entry of load and checks the library it returns.
void call_entry(BuiltinInfillLoad &load)
{
    std::string entry_log;
    const orca_infill_builtin_library *library = nullptr;
    t_entry_log = &entry_log;
    try {
        library = load.entry(&s_host);
    } catch (...) {
        t_entry_log = nullptr;
        load.error = "its entry failed";
        return;
    }
    t_entry_log = nullptr;
    load.error = check_library(infill_pattern(load.pattern), library, entry_log);
    if (load.error.empty()) {
        load.library = library;
        library->set_scaling_factor(SCALING_FACTOR);
    }
}

// Libraries whose entry ran: never unloaded, the entry may have registered handlers or kept the host.
std::vector<SharedLibrary::Handle> s_libraries;

// Opens load.path and checks it.
void open_file(BuiltinInfillLoad &load)
{
    boost::system::error_code ec;
    if (! fs::exists(load.path, ec)) {
        load.error = "missing";
        return;
    }
    std::string error;
    SharedLibrary::Handle library = SharedLibrary::open(load.path, error);
    if (library == nullptr) {
        load.error = "cannot be loaded: " + error;
        return;
    }
    const auto entry = reinterpret_cast<BuiltinInfillEntry>(SharedLibrary::symbol(library, ORCA_INFILL_BUILTIN_ENTRY_V1));
    if (entry == nullptr || SharedLibrary::symbol(library, ORCA_INFILL_ENTRY_V1) != nullptr) {
        // Nothing of the library was called, so nothing refers to it.
        SharedLibrary::close(library);
        load.error = "not an OrcaSlicer pattern library";
        return;
    }
    s_libraries.push_back(library);
    load.entry = entry;
    call_entry(load);
}

std::string milliseconds(double ms)
{
    char text[32];
    std::snprintf(text, sizeof(text), "%.3f ms", ms);
    return text;
}

template<class Fn> void timed(BuiltinInfillLoad &load, Fn &&fn)
{
    const auto start = std::chrono::steady_clock::now();
    fn();
    load.milliseconds = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
}

// ---- State of this process; written on the main thread before seal() only ----

bool                           s_loaded = false;
std::vector<BuiltinInfillLoad> s_loads;
fs::path                       s_folder;
std::atomic<bool>              s_shut_down { false };

// Binds the row of a library that passed every check, or records why it stays unbound.
void bind(BuiltinInfillLoad &load)
{
    if (load.error.empty() && ! InfillPatternLibraryLoader::bind(load))
        load.error = "its pattern is bound already";
    if (! load.error.empty()) {
        load.library = nullptr;
        InfillPatternLibraryLoader::set_unbound(load);
    }
}

// Loads and binds the library of every row, once per process: open(row, load) sets load.file and load.entry and calls
// the entry, or sets load.error.
template<class Open> const std::vector<BuiltinInfillLoad>& load_once(Open &&open)
{
    if (s_loaded)
        return s_loads;
    s_loaded = true;
    assert(! InfillPatternRegistry::sealed());
    for (const InfillPatternLibraryRow &row : InfillPatternRegistry::library_rows()) {
        BuiltinInfillLoad load;
        load.pattern = row.pattern;
        load.name    = row.name;
        timed(load, [&open, &row, &load] { open(row, load); });
        bind(load);
        s_loads.emplace_back(std::move(load));
    }
    return s_loads;
}

